    function initNavbarLinks() {

        r4.settings?.createTumblerSetting({
            name: "navbar-links",
            label: "Ссылки в панели навигации",
            submenu: "Интерфейс",
            classes: [],
            options: [
                {
                    value: "r4-navbar-links-default",
                    text: "Выкл",
                    end: () => setNavbarLinksDefaultFilter(null),
                },
                {
                    value: "r4-navbar-links-last",
                    class: "r4-navbar-links-last",
                    text: "Последние поступления",
                    end: () => setNavbarLinksDefaultFilter("last"),
                },
                {
                    value: "r4-navbar-links-popular",
                    class: "r4-navbar-links-popular",
                    text: "Популярные",
                    end: () => setNavbarLinksDefaultFilter("popular"),
                },
                {
                    value: "r4-navbar-links-soon",
                    class: "r4-navbar-links-soon",
                    text: "В ожидании",
                    end: () => setNavbarLinksDefaultFilter("soon"),
                },
                {
                    value: "r4-navbar-links-watching",
                    class: "r4-navbar-links-watching",
                    text: "Сейчас смотрят",
                    end: () => setNavbarLinksDefaultFilter("watching"),
                },
            ],
        });

        function setNavbarLinksDefaultFilter(filter) {
            function replace(elem) {
                if (elem.id === "rc-search-entry") return;
                const href = elem.getAttribute("href")?.trim();
                if (!href || href.startsWith("#")) return;
                let url;
                try { url = new URL(href, document.baseURI); }
                catch { return; }
                if (url.origin !== location.origin || !["http:", "https:"].includes(url.protocol)) return;
                if (filter) url.searchParams.set("filter", filter);
                else url.searchParams.delete("filter");
                elem.href = url.href;
            }

            const navbar = document.querySelector(".b-topnav");
            if (navbar) {
                navbar.querySelectorAll("a.b-topnav__item-link[href]").forEach(replace);
                navbar.querySelectorAll(".b-topnav__sub_inner .left a[href]").forEach(replace);
            }
        }
    }

