    /* ------------------------------------------------- */
    /* --------------PLAYER-AUTO-PLAY-NEXT-------------- */
    /* ------------------------------------------------- */

    function initAutoPlayNext() {
        window.addEventListener("message", (event) => {
            switch (event.data?.event) {
                case "ended":
                    if (document.body.classList.contains("r4-auto-play-next-enabled")) {
                        r4.player.next();
                    }
                    break;
                case "time":
                    if (
                        event.data.data != 0 &&
                        event.data.data >= event.data.duration - 1 &&
                        document.body.classList.contains("r4-auto-play-next-disabled")
                    ) {
                        r4.player.stop();
                    }
                    break;
            }
        });

        r4.settings?.createTumblerSetting({
            name: "auto-play-next",
            label: "Автопереключение серий",
            submenu: "Плеер",
            classes: [],
            options: [
                {
                    value: "r4-auto-play-next-default",
                    text: "Как в настройках профиля (серии или выкл)",
                },
                {
                    value: "r4-auto-play-next-enabled",
                    class: "r4-auto-play-next-enabled",
                    text: "Быстрое переключение (серии и сезоны)",
                },
                {
                    value: "r4-auto-play-next-disabled",
                    class: "r4-auto-play-next-disabled",
                    text: "Выкл",
                },
            ],
        });
    }

