    function initFonts() {
        function addFont(fontName, fontClass, fontData) {
            Object.keys(fontData).forEach((weight) => {
                const value = fontData[weight];

                GM.addStyle(`

                /* css */

                @font-face {
                    font-family: ${fontName};
                    src: url(data:font/truetype;base64,${value}) format('truetype');
                    font-weight: ${weight};
                    font-style: normal;
                }

                /* !css */

                `);
            });

            GM.addStyle(`

            /* css */

            body.${fontClass} {
                font-family: ${fontName}, sans-serif !important;
            }

            /* !css */

            `);
        }
        r4.settings?.createTumblerSetting({
            name: "font",
            label: "Шрифт",
            submenu: "Интерфейс",
            classes: [],
            options: [
                {
                    value: "r4-font-default",
                    text: "Стандартный",
                },
                {
                    value: "r4-font-averta-cy",
                    class: "r4-font-averta-cy",
                    text: "Averta-CY",
                    start() {
                        addFont("Averta-CY", "r4-font-averta-cy", r4.fonts["Averta-CY"]);
                    },
                },
            ],
        });
    }

