            if (!img) return;

            r4.player.poster(img);

            GM.addStyle(`

            /* css */

            body.r4-player-cover #cdnplayer [style*='${img}'] {
                background-image: url('${img}') !important;
                background-size: 100% auto !important;
                background-position: center !important;
                background-repeat: no-repeat !important;
                filter: blur(30px);
                z-index: -1;
            }

            /* Add a semi-transparent overlay */
            body.r4-player-cover #cdnplayer [style*='${img}']::before {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                right: 0;
                bottom: 0;
                background: rgba(0, 0, 0, 0.5);
                z-index: 0;
            }

            /* Add vignette effect */
            body.r4-player-cover #cdnplayer [style*='${img}']::after {
                content: '';
                position: absolute;
                top: 0;
                left: 0;
                right: 0;
                bottom: 0;
                background: radial-gradient(
                    circle at center,
                    transparent 20%,
                    rgba(0, 0, 0, 0.6) 60%,
                    rgba(0, 0, 0, 0.8) 100%
                );
                z-index: 1;
            }

            /* !css */

            `);
